<script setup lang="ts">
import {ref,onBeforeUnmount} from 'vue'
import {api,type Question} from './api'
import AiSettings from './AiSettings.vue'
const props=defineProps<{question:Question;note:string}>(),emit=defineEmits<{append:[text:string]}>()
interface Context {text:string;pages:number[];truncated:boolean;images:{page:number;url:string}[]}
const configSections=ref<string[]>([]),opened=ref(false),mode=ref('organize'),pdfText=ref(''),prompt=ref(''),includeImages=ref(false),context=ref<Context>(),start=ref(props.question.page_start),end=ref(Math.min(props.question.page_end,props.question.page_start+2)),consent=ref(false),busy=ref(false),reading=ref(false),error=ref(''),draft=ref(''),history=ref<{role:'user'|'assistant';content:string}[]>([]),provider=ref(''),resultMode=ref('')
let controller:AbortController|undefined
async function load(preserveText=false){reading.value=true;error.value='';try{const c=await api<Context>('/questions/'+props.question.id+'/ai-context?'+new URLSearchParams({start_page:String(start.value),end_page:String(end.value),include_images:String(includeImages.value)}));context.value=c;if(!preserveText)pdfText.value=c.text;consent.value=false}catch(e){error.value=String(e)}finally{reading.value=false}}
async function open(){opened.value=!opened.value;if(opened.value&&!context.value)await load()}
async function ask(){if(!consent.value)return;busy.value=true;error.value='';controller=new AbortController();const submitted=prompt.value;try{const result=await api<{answer:string;model:string}>('/questions/'+props.question.id+'/ai-assist',{method:'POST',headers:{'Content-Type':'application/json'},signal:controller.signal,body:JSON.stringify({mode:mode.value,note:props.note,pdf_text:pdfText.value,prompt:submitted,history:mode.value==='discuss'?history.value.slice(-8):[],image_pages:includeImages.value?context.value?.images.map(i=>i.page)||[]:[],consent:true})});draft.value=result.answer;provider.value=result.model;resultMode.value=mode.value;if(mode.value==='discuss')history.value.push({role:'user',content:submitted||'讨论本题解法'},{role:'assistant',content:result.answer.slice(0,12000)});prompt.value=''}catch(e){if((e as Error).name!=='AbortError')error.value=String(e)}finally{busy.value=false}}
function append(){if(!draft.value.trim())return;emit('append','AI 辅助建议（待核对）\n'+draft.value.trim());draft.value=''}
onBeforeUnmount(()=>controller?.abort())
</script>
<template><section class="ai-assistant"><el-button @click="open">{{opened?'收起 AI 帮助':'AI 帮助：整理心得 / 讨论解法'}}</el-button><div v-if="opened"><p>基于当前 PDF 页和你的心得给出建议。需要你主动发送、核对并选择是否采纳；不会自动判断错因。</p><el-collapse v-model="configSections"><el-collapse-item name="settings" title="配置 AI 服务（首次使用）"><AiSettings @saved="configSections=[]"/></el-collapse-item></el-collapse><el-radio-group v-model="mode" :disabled="busy"><el-radio-button value="organize">整理心得</el-radio-button><el-radio-button value="discuss">讨论解法</el-radio-button></el-radio-group><p class="muted">整理模式保留你的原意；讨论模式可继续追问。若题目为图片，请选择附带原页图片，且模型需支持看图。</p><div class="toolbar"><span>取自 PDF 页</span><el-input-number v-model="start" :min="1"/><span>至</span><el-input-number v-model="end" :min="start" :max="start+2"/><el-button :loading="reading" :disabled="busy" @click="load(false)">读取这些页</el-button></div><label>将发送的 PDF 文字（可编辑、删去同页其他题及页脚信息）<el-input v-model="pdfText" type="textarea" :rows="6" :disabled="busy"/></label><p v-if="context?.truncated" class="warnings">文字过长已截断，请核对内容或缩小页码范围。</p><p v-if="context&&!context.text.trim()">没有可提取文字，可附带原页图片，或在上方手动补充。</p><el-checkbox v-model="includeImages" :disabled="busy||reading" @change="load(true)">附带所选页图片（可能含同页其他题与页脚信息）</el-checkbox><div class="ai-image-preview"><img v-for="i in includeImages?context?.images:[]" :key="i.page" :src="i.url" :alt="'将发送 PDF 第 '+i.page+' 页'"/></div><label>{{mode==='organize'?'整理要求（可选）':'我想问 / 继续追问'}}<el-input v-model="prompt" type="textarea" :rows="3" :disabled="busy" :placeholder="mode==='organize'?'例如：保留原意，帮我整理成三条下次行动':'例如：我为什么不能用这个公式？有没有更快的方法？'"/></label><p class="muted">发送范围：上方文字、当前心得、题号/模块/答案；讨论模式还含本题最近四轮对话；勾选后另含预览的页图片。不会发送整个 PDF 或其他题的笔记。服务可能按用量计费。</p><el-checkbox v-model="consent" :disabled="busy">我已核对发送范围，同意发送至配置的 AI 服务</el-checkbox><div class="toolbar"><el-button type="primary" :loading="busy" :disabled="!consent||reading" @click="ask">{{busy?'AI 正在思考…':'发送给 AI'}}</el-button><el-button :disabled="busy" @click="history=[]">清空本题对话</el-button><span v-if="history.length">已讨论 {{history.length/2}} 轮</span></div><el-alert v-if="error" :title="error" type="error" :closable="false"/><article v-if="draft"><h4>{{resultMode==='organize'?'心得整理建议':'解法讨论建议'}} · {{provider}}</h4><p>AI 建议可能有误，请对照原卷核对。可修改以下内容后再追加到心得。</p><el-input v-model="draft" type="textarea" :rows="10"/><el-button type="primary" @click="append">采纳：追加到我的心得</el-button><el-button @click="draft=''">舍弃建议</el-button></article></div></section></template>
